import java.util.ArrayDeque;

public class Solution {
    // Pré-processamento O(n log n) de tempo e memória; consultas O(log n).
    static class Arvore {
        private final int n;
        private final int log;
        private final int[][] up;
        private final int[] profundidade;

        Arvore(int[] pais) {
            if (pais == null || pais.length == 0) throw new IllegalArgumentException("árvore vazia");
            n = pais.length;
            int l = 1;
            while ((1 << l) < n) l++;
            log = l + 1;
            up = new int[log][n];
            profundidade = new int[n];

            // Lista de filhos em arrays (primeiro filho / próximo irmão), sem coleções de boxing.
            int[] primeiroFilho = new int[n];
            int[] proximoIrmao = new int[n];
            java.util.Arrays.fill(primeiroFilho, -1);
            int raiz = -1;
            for (int v = 0; v < n; v++) {
                int p = pais[v];
                up[0][v] = p;
                if (p == -1) {
                    if (raiz != -1) throw new IllegalArgumentException("mais de uma raiz");
                    raiz = v;
                } else {
                    if (p < 0 || p >= n) throw new IllegalArgumentException("pai inválido: " + p);
                    proximoIrmao[v] = primeiroFilho[p];
                    primeiroFilho[p] = v;
                }
            }
            if (raiz == -1) throw new IllegalArgumentException("sem raiz");

            // BFS: profundidades sem recursão (árvores degeneradas não estouram a pilha).
            ArrayDeque<Integer> fila = new ArrayDeque<>();
            fila.add(raiz);
            int visitados = 0;
            while (!fila.isEmpty()) {
                int v = fila.poll();
                visitados++;
                for (int f = primeiroFilho[v]; f != -1; f = proximoIrmao[f]) {
                    profundidade[f] = profundidade[v] + 1;
                    fila.add(f);
                }
            }
            if (visitados != n) throw new IllegalArgumentException("a entrada não forma uma árvore");

            for (int k = 1; k < log; k++) {
                for (int v = 0; v < n; v++) {
                    int meio = up[k - 1][v];
                    up[k][v] = meio == -1 ? -1 : up[k - 1][meio];
                }
            }
        }

        int profundidade(int v) {
            validar(v);
            return profundidade[v];
        }

        int ancestral(int v, int k) {
            validar(v);
            if (k < 0) throw new IllegalArgumentException("k negativo");
            if (k > profundidade[v]) return -1;
            for (int bit = 0; k > 0; bit++, k >>= 1) {
                if ((k & 1) == 1) v = up[bit][v];
            }
            return v;
        }

        int lca(int u, int v) {
            validar(u);
            validar(v);
            if (profundidade[u] < profundidade[v]) { int t = u; u = v; v = t; }
            u = ancestral(u, profundidade[u] - profundidade[v]);
            if (u == v) return u;
            for (int k = log - 1; k >= 0; k--) {
                if (up[k][u] != up[k][v]) {
                    u = up[k][u];
                    v = up[k][v];
                }
            }
            return up[0][u];
        }

        int distancia(int u, int v) {
            return profundidade(u) + profundidade(v) - 2 * profundidade[lca(u, v)];
        }

        private void validar(int v) {
            if (v < 0 || v >= n) throw new IllegalArgumentException("nó inválido: " + v);
        }
    }
}

