import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static Solution.Arvore exemplo() {
        return new Solution.Arvore(new int[] {-1, 0, 0, 1, 1, 2, 4});
    }

    @Test void lcaDoExemplo() {
        var a = exemplo();
        assertEquals(1, a.lca(3, 6));
        assertEquals(0, a.lca(6, 5));
        assertEquals(4, a.lca(4, 6));
        assertEquals(4, a.lca(6, 4));
        assertEquals(2, a.lca(2, 2));
        assertEquals(0, a.lca(0, 6));
    }

    @Test void ancestrais() {
        var a = exemplo();
        assertEquals(6, a.ancestral(6, 0));
        assertEquals(4, a.ancestral(6, 1));
        assertEquals(1, a.ancestral(6, 2));
        assertEquals(0, a.ancestral(6, 3));
        assertEquals(-1, a.ancestral(6, 4));
        assertEquals(-1, a.ancestral(0, 1_000_000_000));
    }

    @Test void distancias() {
        var a = exemplo();
        assertEquals(4, a.distancia(3, 5));
        assertEquals(0, a.distancia(5, 5));
        assertEquals(3, a.distancia(0, 6));
        assertEquals(3, a.profundidade(6));
    }

    @Test void raizForaDoIndiceZero() {
        // raiz é o nó 3
        var a = new Solution.Arvore(new int[] {3, 3, 0, -1, 0});
        assertEquals(0, a.lca(2, 4));
        assertEquals(3, a.lca(1, 4));
        assertEquals(3, a.ancestral(2, 2));
    }

    @Test void arvoreDegeneradaGrande() {
        int n = 200_000;
        int[] pais = new int[n];
        pais[0] = -1;
        for (int i = 1; i < n; i++) pais[i] = i - 1; // uma linha
        var a = new Solution.Arvore(pais);
        assertEquals(n - 1, a.profundidade(n - 1));
        assertEquals(0, a.ancestral(n - 1, n - 1));
        assertEquals(12_345, a.lca(12_345, n - 1));
        assertEquals(n - 1 - 777, a.distancia(777, n - 1));
    }

    @Test void validacoes() {
        assertThrows(IllegalArgumentException.class, () -> new Solution.Arvore(new int[0]));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Arvore(new int[] {-1, -1}));
        assertThrows(IllegalArgumentException.class, () -> new Solution.Arvore(new int[] {1, 0}));
        var a = exemplo();
        assertThrows(IllegalArgumentException.class, () -> a.lca(0, 7));
        assertThrows(IllegalArgumentException.class, () -> a.ancestral(3, -1));
    }
}
